package kr.blackwiki.smp;

import org.bukkit.util.Vector;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class GunRulesTest {
 @TempDir Path dir;
 @Test void fullCycleChargesReloadAndEveryShotForEachType(){for(var kind:GunKind.values()){var s=GunRules.reload(kind,0,kind.capacity+1);for(int i=0;i<kind.capacity;i++)s=GunRules.shot(kind,s.loaded(),s.reserve());assertEquals(new GunRules.Plan(0,0),s,kind.name());}}
 @Test void twoShotShellCycleRequiresThreeShells(){var r=GunRules.reload(GunKind.SHOTGUN,0,3);r=GunRules.shot(GunKind.SHOTGUN,r.loaded(),r.reserve());r=GunRules.shot(GunKind.SHOTGUN,r.loaded(),r.reserve());assertEquals(new GunRules.Plan(0,0),r);}
 @Test void sniperRequiresOneReloadFeeAndOneRoundToFire(){assertEquals(new GunRules.Plan(1,0),GunRules.reload(GunKind.SNIPER,0,1));assertThrows(IllegalStateException.class,()->GunRules.shot(GunKind.SNIPER,1,0));assertEquals(new GunRules.Plan(0,0),GunRules.shot(GunKind.SNIPER,1,1));}
 @Test void invalidAndFullMagazinesDoNotGenerateAmmo(){for(var k:GunKind.values()){for(int n:new int[]{-1,k.capacity+1,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->GunRules.reload(k,n,10));assertThrows(IllegalArgumentException.class,()->GunRules.shot(k,0,-1));assertThrows(IllegalStateException.class,()->GunRules.reload(k,k.capacity,10));assertThrows(IllegalStateException.class,()->GunRules.reload(k,0,0));assertThrows(IllegalStateException.class,()->GunRules.shot(k,0,10));}}
 @Test void partialReloadChargesOnceAndRetainsCapacity(){assertEquals(new GunRules.Plan(2,4),GunRules.reload(GunKind.SHOTGUN,1,5));assertEquals(new GunRules.Plan(6,4),GunRules.reload(GunKind.PISTOL,5,5));}
 @Test void shotgunUserClarificationMeansTwentyFourTotalNotPerPellet(){assertEquals(24,GunKind.SHOTGUN.damage);assertEquals(5,GunKind.SHOTGUN.pellets);assertEquals(4.8,GunKind.SHOTGUN.damage/GunKind.SHOTGUN.pellets,1e-9);}
 @Test void sniperUserClarificationMeansFiveHearts(){assertEquals(10,GunKind.SNIPER.damage);assertEquals(1,GunKind.SNIPER.capacity);}
 @Test void requestedReloadTimesAndDurabilityAreDistinct(){assertEquals(40,GunKind.PISTOL.reloadTicks);assertEquals(30,GunKind.SHOTGUN.reloadTicks);assertEquals(50,GunKind.SNIPER.reloadTicks);assertEquals(250,GunKind.PISTOL.durability);assertEquals(1561,GunKind.SHOTGUN.durability);assertEquals(1561,GunKind.SNIPER.durability);}
 @Test void eachGunHasItsOwnAmmoId(){Set<String> ids=new HashSet<>();for(var k:GunKind.values()){assertTrue(ids.add(k.ammoId));assertSame(k,GunKind.gun(k.id));assertSame(k,GunKind.ammo(k.ammoId));if(k.packId!=null)assertSame(k,GunKind.ammo(k.packId));}assertNull(GunKind.ammo("GUNPOWDER"));assertNull(GunKind.ammo(null));assertNull(GunKind.gun("renamed"));}
 @Test void pricesAndDiscountedTwelvePackMatchRequest(){assertEquals(250000,ShopCatalogue.find("double_barrel_shotgun").buy());assertEquals(1500,ShopCatalogue.find("shotgun_shell").buy());assertEquals(200000,ShopCatalogue.find("heavy_sniper").buy());assertEquals(1500,ShopCatalogue.find("sniper_round").buy());assertEquals(18000,ShopCatalogue.find("sniper_round_pack").buy());assertEquals(18000,ShopCatalogue.find("sniper_round").total(false,12));assertEquals(12,PistolItems.packSize("sniper_round_pack"));}
 @Test void allGunProductsStayOnPageFourAndCannotBeResold(){for(var k:GunKind.values())for(String id:Arrays.asList(k.id,k.ammoId,k.packId)){if(id==null)continue;var p=ShopCatalogue.find(id);assertEquals(ShopCatalogue.Category.SPECIAL,p.category());assertThrows(IllegalArgumentException.class,()->p.total(true,1));}for(var k:GunKind.values())assertThrows(IllegalArgumentException.class,()->ShopCatalogue.find(k.id).total(false,2));}
 @Test void bulkTwelvePacksRetainCorrectQuote(){assertEquals(1152000,ShopCatalogue.find("sniper_round_pack").total(false,64));assertTrue(ShopCatalogue.find("sniper_round_pack").ammo());assertFalse(ShopCatalogue.find("heavy_sniper").ammo());assertTrue(ShopCatalogue.find("heavy_sniper").firearm());}
 @Test void spreadProducesFiveDistinctForwardRaysWithoutMutatingAim(){Vector aim=new Vector(0,0,1),old=aim.clone();var rays=GunRules.directions(GunKind.SHOTGUN,aim);assertEquals(old,aim);assertEquals(5,rays.size());assertEquals(5,new HashSet<>(rays).size());for(var r:rays){assertEquals(GunKind.SHOTGUN.speed,r.length(),1e-9);assertTrue(r.getZ()>0);}}
 @Test void verticalShotgunAimDoesNotProduceNan(){for(var aim:List.of(new Vector(0,1,0),new Vector(0,-1,0)))for(var r:GunRules.directions(GunKind.SHOTGUN,aim)){assertTrue(Double.isFinite(r.length()));assertEquals(3,r.length(),1e-9);assertTrue(r.dot(aim)>0);}}
 @Test void sniperIsOneStraightHighSpeedRay(){Vector aim=new Vector(1,.2,4);var rays=GunRules.directions(GunKind.SNIPER,aim);assertEquals(1,rays.size());assertEquals(8,rays.getFirst().length(),1e-9);assertEquals(0,rays.getFirst().angle(aim),1e-6);}
 @Test void invalidAimCannotLaunch(){for(var aim:List.of(new Vector(),new Vector(Double.NaN,0,1),new Vector(Double.POSITIVE_INFINITY,0,1)))assertThrows(IllegalArgumentException.class,()->GunRules.directions(GunKind.SHOTGUN,aim));}
 @Test void actualThirtyConfigMigratesWithoutChangingUserSettingsOrData()throws Exception{Path cfg=dir.resolve("config.yml"),data=dir.resolve("data.yml");String old="config-version: 30\npistol:\n  enabled: false\ndiscord:\n  bot-token: unit-test-token-123456789\ncustom: keep\n";Files.writeString(cfg,old);Files.writeString(data,"coins: 600000\n");var r=UpgradeService.migrate(cfg,Files.readString(Path.of("src/main/resources/config.yml")));assertEquals(30,r.from());assertEquals(40,r.to());var y=YamlConfiguration.loadConfiguration(cfg.toFile());assertFalse(y.getBoolean("pistol.enabled"));assertEquals("keep",y.getString("custom"));assertEquals("unit-test-token-123456789",y.getString("discord.bot-token"));assertEquals(old,Files.readString(dir.resolve("config.yml.before-4.0.bak")));assertEquals("coins: 600000\n",Files.readString(data));assertFalse(UpgradeService.migrate(cfg,Files.readString(Path.of("src/main/resources/config.yml"))).changed());}
 @Test void futureConfigCannotBeDowngraded()throws Exception{Path cfg=dir.resolve("config.yml");Files.writeString(cfg,"config-version: 41\n");assertThrows(Exception.class,()->UpgradeService.migrate(cfg,Files.readString(Path.of("src/main/resources/config.yml"))));assertEquals("config-version: 41\n",Files.readString(cfg));}
}
